import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import DiscussionHero from 'flarum/forum/components/DiscussionHero';
import username from 'flarum/common/helpers/username';
import extractText from 'flarum/common/utils/extractText';
import classList from 'flarum/common/utils/classList';
import MoreFrom from './MoreFrom';
import { bump, has, mediumOf, t } from '../util';
/** The opening post, when the stream has it loaded. */
export function openingPost(discussion) {
  return app.store.all('posts').find(post => post.discussion?.() === discussion && post.number() === 1) || null;
}

/**
 * Who made it, what it is, and the facts about it: the creator with Follow
 * (ianm/follow-users), the discussion's own hero (its title, tags and
 * whatever other extensions add there), a spec sheet, Appreciate (a like on
 * the opening post, flarum/likes), and the creator's builds, projects and
 * gallery when Garage, Projects or Atrium is installed.
 */
export default class Creator extends Component {
  view() {
    const discussion = this.attrs.discussion;
    const user = discussion.user();
    const side = this.attrs.variant === 'side';
    if (this.attrs.variant === 'facts') {
      return m("section", {
        className: "StudioCreator StudioCreator--facts",
        "aria-label": t('spec.label')
      }, this.specView(), this.actionsView(), this.linksView());
    }
    return m("section", {
      className: classList('StudioCreator', `StudioCreator--${this.attrs.variant}`),
      "aria-label": t('creator.label')
    }, m("div", {
      className: "StudioCreator-who"
    }, user ? m(Link, {
      href: app.route.user(user),
      className: "StudioCreator-avatar",
      tabindex: "-1",
      "aria-hidden": "true"
    }, m(Avatar, {
      user: user
    })) : m("span", {
      className: "StudioCreator-avatar"
    }, m(Avatar, {
      user: null
    })), m("div", {
      className: "StudioCreator-name"
    }, user ? m(Link, {
      href: app.route.user(user)
    }, username(user)) : username(user), user ? m("div", {
      className: "StudioCreator-facts"
    }, this.facts(user)) : null), !side ? this.followButton() : null), side ? this.followButton() : null, m(DiscussionHero, {
      discussion: discussion
    }), side ? this.specView() : null, side ? this.actionsView() : null, side ? this.linksView() : null, side && user ? m(MoreFrom, {
      discussion: discussion
    }) : null);
  }
  facts(user) {
    const parts = [];
    const works = user.discussionCount?.();
    const followers = user.attribute('followerCount');
    if (typeof works === 'number') parts.push(extractText(t('creator.works', {
      count: works
    })));
    if (typeof followers === 'number') parts.push(extractText(t('creator.followers', {
      count: followers
    })));
    return parts.join(' · ');
  }
  followButton() {
    const user = this.attrs.discussion.user();
    const me = app.session.user;
    if (!user || !has('ianm-follow-users') || user === me) return null;
    const followed = !!user.attribute('followed');
    if (me && !followed && !user.attribute('canBeFollowed')) return null;
    return m(Button, {
      className: classList('Button StudioCreator-follow', {
        'Button--primary': !followed
      }),
      icon: followed ? 'fas fa-check' : 'fas fa-user-plus',
      "aria-pressed": followed ? 'true' : 'false',
      onclick: () => {
        if (!me) {
          app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
          return;
        }
        user.save({
          followUsers: followed ? null : 'follow'
        }).then(bump, bump);
      }
    }, followed ? t('creator.following') : t('creator.follow', {
      name: username(user)
    }));
  }

  /** The spec sheet: the facts a reader of a work wants, from what the forum knows. */
  specItems() {
    const discussion = this.attrs.discussion;
    const medium = mediumOf(discussion);
    const pictures = discussion.attribute('studioImages') || 0;
    const views = discussion.attribute('views');
    const rows = [];
    if (medium) rows.push([t('spec.medium'), medium.name()]);
    if (pictures) rows.push([t('spec.pictures'), String(pictures)]);
    rows.push([t('spec.posted'), m("time", {
      dateTime: discussion.createdAt()?.toISOString()
    }, dayjs(discussion.createdAt()).format('LL'))]);
    rows.push([t('spec.replies'), String(Math.max(0, (discussion.commentCount() || 1) - 1))]);
    if (typeof views === 'number') rows.push([t('spec.views'), String(views)]);
    return rows;
  }
  specView() {
    return m("dl", {
      className: "StudioSpec"
    }, this.specItems().map(([label, value]) => m("div", {
      className: "StudioSpec-row"
    }, m("dt", null, label), m("dd", null, value))));
  }
  actionsView() {
    const post = openingPost(this.attrs.discussion);
    if (!post || !has('flarum-likes') || typeof post.canLike !== 'function' || post.isHidden()) return null;
    const me = app.session.user;
    const liked = !!me && (post.likes?.() || []).some(u => u === me);
    const count = post.likesCount?.() || 0;
    if (!post.canLike() && !liked) {
      return count ? m("div", {
        className: "StudioCreator-likes"
      }, t('creator.appreciated', {
        count
      })) : null;
    }
    return m(Button, {
      className: classList('Button StudioCreator-appreciate', {
        'Button--primary': !liked,
        active: liked
      }),
      icon: liked ? 'fas fa-heart' : 'far fa-heart',
      "aria-pressed": liked ? 'true' : 'false',
      onclick: () => {
        const like = !liked;
        post.save({
          isLiked: like
        }).then(bump, bump);

        // As flarum/likes does: show it at once, the response fills in the rest.
        const relationships = post.data.relationships ??= {};
        const data = (relationships.likes ??= {
          data: []
        }).data;
        const i = data.findIndex(entry => entry.id === me.id());
        if (i >= 0) data.splice(i, 1);
        if (like) data.unshift({
          type: 'users',
          id: me.id()
        });
        post.pushAttributes({
          likesCount: Math.max(0, count + (like ? 1 : -1))
        });
        bump();
      }
    }, t('creator.appreciate', {
      count
    }));
  }

  /** The creator's other homes on this forum, from the extensions that have them. */
  linksView() {
    const user = this.attrs.discussion.user();
    if (!user) return null;
    const links = [['user.garage', 'creator.builds', 'fas fa-wrench'], ['user.projects', 'creator.projects', 'fas fa-folder-open'], ['atrium.user', 'creator.gallery', 'far fa-images']].filter(([route]) => app.routes[route]);
    if (!links.length) return null;
    return m("nav", {
      className: "StudioCreator-links",
      "aria-label": t('creator.links_label', {
        name: username(user)
      })
    }, links.map(([route, key, icon]) => m(Link, {
      className: "Button Button--flat StudioCreator-link",
      href: app.route(route, {
        username: user.slug()
      })
    }, m("i", {
      className: `icon ${icon}`,
      "aria-hidden": "true"
    }), " ", t(key))));
  }
}
flarum.reg.add('ernestdefoe-studio', 'forum/work/Creator', Creator);